// std::string under the Itanium C++ ABI of Android's clang, with its libc++, on x86-64 and AArch64,
// for core/nvrhi.ts (its import of "./nvrhi_abi" takes this file on Android, core/nvrhi_abi.win32.ts
// on Windows): debug names for the descs NVRHI takes. The classes and the structs, generated by
// tools/gen_nvrhi_classes.py, are in core/nvrhi_classes.linux.ts, with std::string as libc++ lays
// it out (basic_string_char).

import "./nvrhi_classes";

export namespace nvrhi {

    // libc++'s std::string (24 bytes, three words in __rep_): short, the first byte is the size
    // times two (its low bit set would make the string long), followed by up to 22 characters and
    // their terminating zero
    export type StdString = basic_string_char;

    // An std::string holding name, for a desc's debugName: only a short string (22 characters or
    // fewer) can be made here, as a longer one is allocated by C++; empty for a longer name.
    export function stdString(name: string): StdString {
        const empty: StdString = [[0, 0, 0]];
        const chars = <Ref<u8>><Opaque>name;
        let size = 0;
        while (Deref(chars[size]) != 0) {
            size++;
            if (size > 22) {
                return empty;
            }
        }

        // byte 0 is the size times two, byte k + 1 character k
        let word0: u64 = size * 2;
        let word1: u64 = 0;
        let word2: u64 = 0;
        let shift: u64 = 256;
        for (let i = 0; i < size; i++) {
            const byte = i + 1;
            if (byte == 8 || byte == 16) {
                shift = 1;
            }
            const char: u64 = Deref(chars[i]);
            if (byte < 8) {
                word0 += char * shift;
            } else if (byte < 16) {
                word1 += char * shift;
            } else {
                word2 += char * shift;
            }
            shift *= 256;
        }

        return [[word0, word1, word2]];
    }

    // An std::string's size: a long one's (the first byte's low bit set) is its second word
    export function stdStringSize(value: StdString): int {
        const rep = value.__rep_;
        if ((rep._0 & 1) != 0) {
            return <int>rep._1;
        }

        return <int>((rep._0 & 0xff) >> 1);
    }

    // Whether an std::string (NVRHI's copy of a debug name, say) is short and holds text: its
    // characters and terminating zero, read byte by byte from after its size byte
    export function stdStringIs(value: StdString, text: string): boolean {
        if ((value.__rep_._0 & 1) != 0) {
            return false;
        }

        const size = stdStringSize(value);
        const chars = <Ref<u8>><Opaque>text;
        let copy = value;
        const bytes = <Ref<u8>><Opaque>Ref(copy);
        for (let i = 0; i <= size; i++) {
            if (Deref(bytes[i + 1]) != Deref(chars[i])) {
                return false;
            }
        }

        return true;
    }

    // libc++'s std::vector: {__begin_, __end_, __cap_}
    // A std::vector<T> over items' elements, for a desc NVRHI copies: nothing destroys it here,
    // and items has to stay alive during the call.
    export function stdVector<T>(items: T[]): vector<T> {
        if (items.length == 0) {
            return [null, null, null];
        }

        const first = Ref(items[0]);
        const end = <Ref<T>><Opaque>(<index><Opaque>first + items.length * sizeof<T>());
        return [first, end, end];
    }

    // A std::vector<T>'s size
    export function stdVectorSize<T>(items: vector<T>): int {
        const a = <index><Opaque>items.__begin_;
        const b = <index><Opaque>items.__end_;
        return <int>((b - a) / sizeof<T>());
    }
}
